firstRawText:
{
  "schemaVersion": "ride-output-v2.2.0",
  "label": {
    "text": "总距离 56 公里、爬升 904 米的骑行",
    "conclusionType": "fact",
    "claimIds": [
      "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:metric.distanceM",
      "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:metric.elevationGainM"
    ]
  },
  "overallAssessment": {
    "text": "本次骑行总距离 56 公里，移动时长 2 小时 9 分钟，平均速度 26.1 km/h，平均功率 159W，整体为一次中等强度的耐力骑行。",
    "conclusionType": "fact",
    "claimIds": [
      "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:metric.distanceM",
      "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:timing.movingDurationS",
      "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:speed.mean",
      "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.mean"
    ]
  },
  "highlights": [
    {
      "text": "本次骑行包含 3 段代表性爬坡，其中最长一段爬坡距离 8.1 公里、平均坡度 5.8%，用时 25 分钟。",
      "conclusionType": "fact",
      "claimIds": [
        "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.distanceM",
        "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.averageGrade",
        "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.span"
      ]
    },
    {
      "text": "10 秒峰值平均功率达到 417W，显示出较强的短时爆发能力。",
      "conclusionType": "fact",
      "claimIds": [
        "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.peakAverage.10s"
      ]
    }
  ],
  "dimensions": [
    {
      "dimensionId": "pacingExecution",
      "assertions": [
        {
          "text": "本次骑行总距离 56 公里，移动时长 2 小时 9 分钟，总用时 2 小时 20 分钟，平均速度 26.1 km/h。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:metric.distanceM",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:timing.movingDurationS",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:metric.elapsedDurationS",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:speed.mean"
          ]
        },
        {
          "text": "骑行过程中共出现 10 次停车，速度变异系数为 37.6%，速度波动较大。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:stops.count",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:speed.coefficientOfVariation"
          ]
        },
        {
          "text": "巡航段 1 平均速度 34.17 km/h，巡航段 2 平均速度 31.01 km/h，两段巡航速度相近，配速执行较为一致。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.cruise.cruise-0-2397.speed.mean",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.cruise.cruise-1-3117.speed.mean"
          ]
        },
        {
          "text": "地形分类覆盖率为 100%，其中爬坡段累计 24.7 公里，平路段 12.7 公里，下坡段 18.3 公里。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:terrain.classifiedCoverageRatio",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:terrain.trendClimbDistanceM",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:terrain.trendFlatDistanceM",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:terrain.trendDescentDistanceM"
          ]
        }
      ]
    },
    {
      "dimensionId": "climbPerformance",
      "assertions": [
        {
          "text": "本次骑行累计爬升 904 米，下降 414 米，包含 8 段爬坡、8 段下坡和 15 段平路。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:metric.elevationGainM",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:metric.elevationLossM",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:terrain.climbRunCount",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:terrain.descentRunCount",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:terrain.flatRunCount"
          ]
        },
        {
          "text": "代表性爬坡中，最长一段爬坡距离 8.1 公里、平均坡度 5.8%、净爬升 467 米，用时 25 分钟，平均功率 284W。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.distanceM",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.averageGrade",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.netElevationGainM",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.span",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.power.mean"
          ]
        },
        {
          "text": "另一段代表性爬坡距离 6.4 公里、平均坡度 4.4%，用时 20 分钟，平均功率 207W，爬坡强度相对适中。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-24698-31062.distanceM",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-24698-31062.averageGrade",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-24698-31062.span",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-24698-31062.power.mean"
          ]
        }
      ]
    },
    {
      "dimensionId": "powerOutput",
      "assertions": [
        {
          "text": "平均功率 159W，归一化功率 218W，平均功率体重比 2.27 W/kg，强度因子 1.09。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.mean",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.normalizedW",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.averageWkg",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.intensityFactor"
          ]
        },
        {
          "text": "功率区间分布：Z1 占 31%，Z2 占 15%，Z3 占 12%，Z4 占 9%，Z5 占 10%，Z6 占 16%，Z7 占 8%，高强度区间（Z5-Z7）合计占 34%。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.z1",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.z2",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.z3",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.z4",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.z5",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.z6",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.z7",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.highIntensityCombined"
          ]
        },
        {
          "text": "功率变异系数为 66.2%，功率波动较大，这与地形起伏和多次停车相伴出现。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.coefficientOfVariation"
          ]
        },
        {
          "text": "10 秒峰值平均功率 417W，20 秒峰值平均功率 377W，30 秒峰值平均功率 349W，短时爆发输出较强。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.peakAverage.10s",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.peakAverage.20s",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.peakAverage.30s"
          ]
        }
      ]
    },
    {
      "dimensionId": "intensityAndTrainingLoad",
      "assertions": [
        {
          "text": "本次骑行训练压力指数（TSS）为 253.3，强度因子 1.09，属于较高负荷的单次训练。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.trainingStressScore",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.intensityFactor"
          ]
        },
        {
          "text": "活动消耗能量 1576 千卡，移动时长 2 小时 9 分钟，平均功率 159W。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:metric.activityEnergyKcal",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:timing.movingDurationS",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.mean"
          ]
        },
        {
          "text": "高强度区间（Z5-Z7）合计占比 34%，说明本次骑行包含较多高强度输出，训练负荷较高。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.highIntensityCombined"
          ]
        }
      ]
    },
    {
      "dimensionId": "cadenceStrategy",
      "assertions": [
        {
          "text": "平均踏频 70 rpm（部分数据缺失），踏频区间分布：低踏频 19%，平稳踏频 42%，耐力踏频 35%，高踏频 4%，极高踏频 0%。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.mean",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.zone.low",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.zone.steady",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.zone.endurance",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.zone.high",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.zone.very-high"
          ]
        },
        {
          "text": "巡航段 1 平均踏频 83 rpm，巡航段 2 平均踏频 71 rpm，两段巡航踏频存在差异。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.cruise.cruise-0-2397.cadence.mean",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.cruise.cruise-1-3117.cadence.mean"
          ]
        },
        {
          "text": "爬坡段踏频相对较低，如最长爬坡段平均踏频 77 rpm，而平路段踏频在 65-67 rpm 之间，踏频策略随地形变化。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.climb.event-climb-47924-55979.cadence.mean",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.terrain.terrain-flat-2048.23-5344.94.cadence.mean",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.terrain.terrain-flat-5841.41-7729.49.cadence.mean"
          ]
        }
      ]
    },
    {
      "dimensionId": "crossSensorCoordination",
      "assertions": [
        {
          "text": "功率与速度的同窗口覆盖率为 100%，功率与踏频的同窗口覆盖率为 96%，表明功率、速度、踏频数据在时间上高度对齐。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:relation.fixed.power-speed.aggregate",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:relation.fixed.power-cadence.aggregate"
          ]
        },
        {
          "text": "功率与速度、功率与踏频的同窗口覆盖率高，说明各传感器数据同步良好，可支持后续分析。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:relation.fixed.power-speed.aggregate",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:relation.fixed.power-cadence.aggregate"
          ]
        }
      ]
    }
  ],
  "suggestions": [
    {
      "text": "本次骑行高强度区间占比较高，建议后续安排低强度恢复骑行，以促进恢复。",
      "conclusionType": "suggestion",
      "claimIds": [
        "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.zone.highIntensityCombined"
      ],
      "riskNote": "恢复建议基于本次高强度占比，不构成恢复状态断言。"
    },
    {
      "text": "巡航段踏频差异较大，下次骑行可尝试保持更一致的踏频，以提高骑行经济性。",
      "conclusionType": "suggestion",
      "claimIds": [
        "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.cruise.cruise-0-2397.cadence.mean",
        "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.cruise.cruise-1-3117.cadence.mean"
      ],
      "riskNote": "踏频数据部分缺失，建议仅供参考。"
    }
  ],
  "limitations": [
    "terrain.climbRunCount:AGGREGATED_FROM_8_WINDOWS",
    "terrain.flatRunCount:AGGREGATED_FROM_15_WINDOWS",
    "terrain.descentRunCount:AGGREGATED_FROM_8_WINDOWS",
    "heartRate:SERIES_MISSING",
    "climb.representativeClimbCount:AGGREGATED_FROM_5_WINDOWS",
    "relation.fixed.power-speed.aggregate:AGGREGATED_FROM_249_WINDOWS",
    "relation.fixed.power-cadence.aggregate:AGGREGATED_FROM_196_WINDOWS"
  ]
}
